#!/usr/bin/env node
// Evidence-derived cloud-only view; never upgrades parity from a source mapping.
import { k4cloudFixtures } from './k4cloud-fixtures.mjs';
import { readJson } from './k4-oracle.mjs';
import { writeFile } from 'node:fs/promises';

const inventory = await readJson('docs/kitten4-block-coverage.json');
const evidence = await readJson('docs/k4cloud-evidence.json');
const cases = await k4cloudFixtures();
const rows = inventory.rows.filter(r => /cloud_|ranking/.test(r.type));
const lines = ['# K4 cloud 官方离线证据覆盖表', '',
  '<!-- Generated by node tools/compat/k4cloud-coverage.mjs; no parity promotion from oracle-only evidence. -->', '',
  '这是 `docs/kitten4-block-coverage.json` 云类别的证据视图，不取代全表。官方逐帧采样、JS证据检查及Rust双VM回归已执行；12项数据域通过后升级，5项舞台/排行榜仍partial，未宣称本地渲染像素相等。', '',
  '| type | 全表语义（生成时） | 实际执行的原创官方夹具 | 舞台证据 |',
  '| --- | --- | --- | --- |'];
for (const row of rows) {
  const names = Object.entries(cases).filter(([name, { project }]) => {
    const blocks = Object.values(project.theatre.actors)[0].block_data_json.blocks;
    return evidence.cases[name].executedBlocks.some(id => blocks[id]?.type === row.type);
  }).map(([name]) => name);
  if (!names.length) throw new Error(`No actual official block event for ${row.type}`);
  const visual = /show_hide_cloud/.test(row.type) ? 'monitors: PIXI 文本、部件 visible、bounds、截图' :
    /ranking/.test(row.type) ? 'ranking: Redux show/var_id/value、DOM loading、截图' : '逐帧 typed 变量/列表；不声明像素相等';
  lines.push(`| \`${row.type}\` | ${row.semantics} | ${names.join('、')} | ${visual} |`);
}
lines.push('', '## 升级规则', '',
  '- 全表来源：`tools/compat/k4-block-catalog.mjs::mappingStatus`。显式lowering不代表一致性；cloudDataTypes精确列出12项经双VM回归的数据域，赋予offline-oracle-verified。其余云UI保持partial。Markdown/JSON全表均由生成器更新。',
  '- 本视图要求 `executedBlocks` 里出现真实官方 block event，而非只在夹具 JSON 中出现块名。17 个 cloud/ranking 类型均实际执行，5 件夹具共 138 update。',
  '- 官方离线证据 ≠ NekoC 已通过。本轮主会话已运行cargo test --all-targets（k4cloud 5项、既有云18项均通过）；UI类未有本地浏览器等价证明，不能升级。单凭本视图或JS自检不得升级。',
  '- 可升级范围只能写“匿名离线主路径”；在线身份/权限、后端排名内容、并发、断线重连、服务器持久化不包含在离线证据内。公开/私有只验证官方离线计算分支，不是假登录测试。',
  '- 普通监视器改动不能替代 cloud 监视器证据；cloud 元数据 visible 不反映脚本显隐，必须看官方 stageWidgets。排行榜 loading 壳与真实榜单内容应分开列。', '');
await writeFile('docs/k4cloud-coverage.md', lines.join('\n'));
console.log(`${rows.length} cloud/ranking rows; no unverified promotion`);
